window.kbPageData["views/entry/k-0a6da28c772630a4"] = {"key":"entry/k-0a6da28c772630a4","state":{"route":"entry/k-0a6da28c772630a4"},"node":{"id":"k-0a6da28c772630a4","mode":"k","title":"全国统一大市场","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":["全国统一大市场建设"],"qs":["政治理论必刷100题#41","江苏 2025 A类 行测#6","江苏 2025 B类 行测#6","江苏 2025 C类 行测#6"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":2,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["market"],"主类":["概念与词义"],"出处性质":["专项题干","机构注释"],"学科":["经济"],"来源主题":["发展与治理"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"全国统一大市场是在全国范围内以统一的市场基础制度规则为基础，使商品和要素资源能够跨地区顺畅流动、经营主体能够公平竞争的市场体系。","review":{"title":"全国统一大市场","type":"概念与词义","definition":"全国统一大市场是在全国范围内以统一的市场基础制度规则为基础，使商品和要素资源能够跨地区顺畅流动、经营主体能够公平竞争的市场体系。","explanation":"2024年党的二十届三中全会《决定》提出推动市场基础制度规则统一、市场监管公平统一、市场设施高标准联通。《关于完善价格治理机制的意见》要求废止妨碍全国统一大市场建设和公平竞争的价格政策，防止政府对价格形成的不当干预。","basis":"据关联原题及所列出处编释。","references":[{"source":"reform","location":"构建全国统一大市场"}],"related":["k-89c1d03096d04b0b","k-6e663bb030341b18"],"domain":"经济","examFocus":{"政治理论必刷100题#41":"从基本公共服务收费、市场价格监管和公共数据定价入手，辨清政府管理与市场调节的边界。","江苏 2025 A类 行测#6":"按改革举措所针对的对象，核对其在党的二十届三中全会《决定》中的归属。"}},"aspects":[{"title":"清理妨碍公平竞争的价格政策","uses":[{"unit":"Q1","role":"直接考查","use":"本题要求选出不正确的价格治理表述。C项关于废止妨碍统一市场和公平竞争的价格政策符合《意见》。B项将公办养老、托育、医疗机构基本服务收费写为全面放开，相关基本服务收费实行政府指导价管理，故选B。","evidence":"废止妨碍全国统一大市场建设和公平竞争的价格政策","qids":["政治理论必刷100题#41"]}]},{"title":"规则统一、监管公平与设施联通","uses":[{"unit":"Q2","role":"直接考查","use":"本题三卷同题。②对应《决定》中构建全国统一大市场的部署，属于构建高水平社会主义市场经济体制的举措，与③④同选，答案为D。","evidence":"推动市场基础制度规则统一、市场监管公平统一、市场设施高标准联通","qids":["江苏 2025 A类 行测#6","江苏 2025 B类 行测#6","江苏 2025 C类 行测#6"]}]}],"sources":[{"id":"4c18d7c76ff0f014","label":"全国统一大市场建设","topic":"发展与治理","category":"非时政","text":"1.全国统一大市场建设\n建设全国统一大市场，不仅是构建新发展格局、推动高质量发展的需要，而且是赢得国\n际竞争主动权的需要。我国作为全球第二大消费市场，必须把全国统一大市场建设好，增强\n我们从容应对风险挑战的底气。\n纵深推进全国统一大市场建设，基本要求是“五统一、一开放”。“五统一”，就是统\n一市场基础制度，特别是实现产权保护、公平竞争、质量标准等制度的统一；统一市场基础\n设施，打通物流、资金流、信息流，健全现代商贸流通体系；统一政府行为尺度，地方在推\n动经济发展特别是招商引资时，哪些能干哪些不能干有明确规矩，不能各行其是；统一市场\n监管执法，明确市场监管行政处罚裁量基准，一把尺子量到底；统一要素资源市场，促进自\n由流动、高效配置，减少资源错配和闲置浪费。“一开放”，就是持续扩大开放，实行对内\n对外开放联通，不搞封闭运行。\n——《求是》杂志","source":{"doc":"6cbfb01fe723bba64b75","first":7,"last":8,"page":7,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#41":{"paper":"政治理论必刷100题","n":41,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",12],"asrc":["国省考政治理论必刷100题.pdf",57],"card":"b68891a815e15da730973a4d","links":[{"id":"k-0a6da28c772630a4","role":"直接考查","why":"考查统一大市场建设对清理妨碍公平竞争的价格政策的要求。"}]},"江苏 2025 A类 行测#6":{"paper":"江苏 2025 A类 行测","n":6,"mod":"政治理论","src":["98687766ac277f427cd6.pdf",2],"asrc":["4fe8e0544dd7b47699d2.pdf",3],"card":"1b4efc1ea7c5fb799d708f3e","links":[{"id":"k-0a6da28c772630a4","role":"直接考查","why":"考查全国统一大市场在规则、监管和设施联通方面的要求及其政策归属。"}]},"江苏 2025 B类 行测#6":{"paper":"江苏 2025 B类 行测","n":6,"mod":"政治理论","src":["91e0d9fd02ca7ec6d61f.pdf",2],"asrc":["f2ff67a0f2a2f7e8e926.pdf",3],"card":"aca47d95f03ee53d99c8e0d3","links":[{"id":"k-0a6da28c772630a4","role":"直接考查","why":"三项要求属于构建全国统一大市场的部署，对应《决定》的市场经济体制建设部分。"}]},"江苏 2025 C类 行测#6":{"paper":"江苏 2025 C类 行测","n":6,"mod":"政治理论","src":["ffc394a1c160f331ec57.pdf",2],"asrc":["d1de3b437151c05b769e.pdf",3],"card":"233392ae527e2b0d3e48fb77","links":[{"id":"k-0a6da28c772630a4","role":"直接考查","why":"三项要求属于《决定》构建高水平社会主义市场经济体制中的全国统一大市场部署。"}]}},"terms":{"k-89c1d03096d04b0b":{"id":"k-89c1d03096d04b0b","mode":"k","type":"制度与规则","title":"全国统一大市场建设中的竞争治理","qs":[],"count":2},"k-6e663bb030341b18":{"id":"k-6e663bb030341b18","mode":"k","type":"概念与词义","title":"国内大循环","qs":[],"count":2}},"references":{"reform":{"name":"《中共中央关于进一步全面深化改革、推进中国式现代化的决定》（2024年）","url":"https://www.miit.gov.cn/xwdt/szyw/art/2024/art_7ba61714bf074c29b0135ddfe4c1e7cd.html"}},"topics":[{"slug":"market","title":"统一大市场与公平竞争"}],"units":{"k-0a6da28c772630a4":[["政治理论必刷100题#41"],["江苏 2025 A类 行测#6","江苏 2025 B类 行测#6","江苏 2025 C类 行测#6"]]}};
